class MinCost {
    /**
     * * Write a function to find the minimum cost path to reach (m, n) from (0, 0) for the given cost matrix cost[][] and a position (m, n) in cost[][].
     *
     * > minCost([[1, 2, 3], [4, 8, 2], [1, 5, 3]], 2, 2)
     * 8
     * > minCost([[2, 3, 4], [5, 9, 3], [2, 6, 4]], 2, 2)
     * 12
     * > minCost([[3, 4, 5], [6, 10, 4], [3, 7, 5]], 2, 2)
     * 16
     */
    public static int minCost(List<List<Integer>> cost, int m, int n) {
        // Initialize a 2D array of size (m+1) x (n+1) filled with zeros
        int[][] d = new int[m + 1][n + 1];
        // Loop over rows from 0 to m
        for (int i = 0; i <= m; i++) {
            // Loop over columns from 0 to n
            for (int j = 0; j <= n; j++) {
                // Assigning i1 to current row index, j1 to current column index
                int i1 = i;
                int j1 = j;
                // Variables to store costs from neighboring cells
                int min1 = Integer.MAX_VALUE;
                int min2 = Integer.MAX_VALUE;
                int min3 = Integer.MAX_VALUE;
                // Check if current cell is at (0,0)
                if (i1 == 0 && j1 == 0) {
                    // Base case: cost at starting point
                    d[i1][j1] = cost.get(i1).get(j1);
                } else {
                    // If above row exists, get cost from the cell above
                    if (i1 - 1 >= 0) {
                        min1 = d[i1 - 1][j1] + cost.get(i1).get(j1);
                    }
                    // If left column exists, get cost from the cell to the left
                    if (j1 - 1 >= 0) {
                        min2 = d[i1][j1 - 1] + cost.get(i1).get(j1);
                    }
                    // If diagonal cell exists, get cost from diagonal
                    if (i1 - 1 >= 0 && j1 - 1 >= 0) {
                        min3 = d[i1 - 1][j1 - 1] + cost.get(i1).get(j1);
                    }
                    // Assign the minimum of the three possible costs
                    int[] temp = {min1, min2, min3};
                    Arrays.sort(temp);
                    d[i1][j1] = temp[0];
                }
            }
        }
        // Return the cost to reach cell (m, n)
        return d[m][n];
    }
}

