class SortMatrix {
    /**
     * * Write a function to sort a given matrix in ascending order according to the sum of its rows.
     *
     * > sortMatrix([[1, 2, 3], [2, 4, 5], [1, 1, 1]])
     * [[1, 1, 1], [1, 2, 3], [2, 4, 5]]
     * > sortMatrix([[1, 2, 3], [-2, 4, -5], [1, -1, 1]])
     * [[-2, 4, -5], [1, -1, 1], [1, 2, 3]]
     * > sortMatrix([[5, 8, 9], [6, 4, 3], [2, 1, 4]])
     * [[2, 1, 4], [6, 4, 3], [5, 8, 9]]
     */
    public static List<List<Integer>> sortMatrix(List<List<Integer>> m) {
        if (m == null || m.size() == 0) {
            return m;
        }
        List<List<Integer>> o = new ArrayList<>();
        for (int i = 0; i < m.size(); i++) {
            o.add(m.get(i));
        }
        for (int x = 0; x < o.size(); x++) {
            for (int y = 0; y < o.size() - 1; y++) {
                int a = 0, b = 0;
                List<Integer> dx = o.get(y);
                List<Integer> dy = o.get(y + 1);
                for (Integer num : dx) {
                    a += num;
                }
                for (Integer num : dy) {
                    b += num;
                }
                if (a > b) {
                    List<Integer> temp = o.get(y);
                    o.set(y, o.get(y + 1));
                    o.set(y + 1, temp);
                }
            }
        }
        return o;
    }
}

