class SquarePerimeter {
    /**
     * * Write a function to find the perimeter of a square.
     *
     * > squarePerimeter(10)
     * 40
     * > squarePerimeter(5)
     * 20
     * > squarePerimeter(4)
     * 16
     */
    public static int squarePerimeter(int a) {
        int b = a;
        int c = 0;
        for (int i = 0; i < 4; i++) {
            c += b;
            int d = b - 1;
            b = d + 1;
        }
        return c;
    }
}

