     * [2, 4, 6, 8, 10, 12, 14, 16, 18]
     */
    public static List<Integer> multiplesOfNum(int m, int n) {
        List<Integer> qwe = new ArrayList<>();
        int uio = 0;
        int zxz = 1;
        while (zxz <= m) {
            uio = n * zxz;
            qwe.add(uio);
            zxz++;
        }
        return qwe;
    }
}

